(()=>{
const REFRESH=30*60*1000;let tide={status:"UNAVAILABLE",points:{},generated_at:null};
const $=id=>document.getElementById(id),num=v=>v===null||v===undefined||v===""||Number.isNaN(Number(v))?null:Number(v),fmt=(v,d=2)=>{v=num(v);return v===null?"—":Number(v.toFixed(d)).toString()};
function style(){if($("tideStyles"))return;const s=document.createElement("style");s.id="tideStyles";s.textContent=`.tide-panel{overflow:hidden}.tide-grid{display:grid;grid-template-columns:170px minmax(220px,1.2fr) minmax(360px,1.5fr);gap:14px;align-items:stretch;margin-top:15px}.tide-now,.tide-chart-wrap,.tide-metrics>div{border:1px solid #e3edf3;border-radius:16px;background:linear-gradient(180deg,#fbfdfe,#f2f7fa)}.tide-now{padding:15px;display:flex;flex-direction:column;justify-content:center}.tide-now>span,.tide-metrics span{font-size:9px;color:#7b8e9b}.tide-now>b{font-size:34px;color:#123a57;line-height:1;margin:6px 0 4px;font-variant-numeric:tabular-nums}.tide-now>small,.tide-metrics small{font-size:8px;color:#94a3ad;line-height:1.3}.tide-trend{margin-top:12px;align-self:flex-start;border-radius:999px;padding:6px 9px;font-size:9px;font-style:normal;font-weight:800}.tide-trend.rising{background:#e5f5fd;color:#0879b2}.tide-trend.falling{background:#eef1fb;color:#5367a8}.tide-trend.turning{background:#fff5da;color:#947014}.tide-trend.unknown{background:#f2f5f7;color:#71828f}.tide-chart-wrap{padding:10px 10px 6px;min-width:0}.tide-chart-wrap svg{width:100%;height:128px;display:block}.tide-line{stroke:#168bd0;stroke-width:3;vector-effect:non-scaling-stroke}.tide-axis{stroke:#dce8ef;stroke-width:1;vector-effect:non-scaling-stroke}.tide-empty{fill:#91a0aa;font-size:12px}.tide-chart-caption{display:flex;justify-content:space-between;color:#91a0aa;font-size:8px;padding:0 4px 2px}.tide-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.tide-metrics>div{padding:12px;min-width:0}.tide-metrics b{display:block;color:#123a57;font-size:16px;line-height:1.15;margin:5px 0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.tide-foot{display:flex;justify-content:space-between;gap:14px;margin-top:11px;padding-top:10px;border-top:1px solid #e8f0f5;color:#84939e;font-size:8px;line-height:1.45}.tide-foot span:last-child{text-align:right;max-width:58%}@media(max-width:900px){.tide-grid{grid-template-columns:150px 1fr}.tide-metrics{grid-column:1/-1;grid-template-columns:repeat(4,1fr)}}@media(max-width:780px){.tide-grid{grid-template-columns:1fr}.tide-metrics{grid-column:auto;grid-template-columns:repeat(2,1fr)}.tide-foot{display:grid;gap:4px}.tide-foot span:last-child{text-align:left;max-width:none}.tide-chart-wrap svg{height:116px}}`;document.head.appendChild(s)}
function ageLabel(value){const t=Date.parse(value||"");if(!Number.isFinite(t))return "chưa có thời gian";const h=Math.max(0,(Date.now()-t)/3600000);return h<1?`${Math.round(h*60)} phút trước`:h<24?`${Math.round(h)} giờ trước`:`${Math.round(h/24)} ngày trước`}
function timeLabel(x){if(!x?.time_iso)return "—";return new Date(x.time_iso).toLocaleString("vi-VN",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false})}
function trendLabel(v){return v==="RISING"?["Đang lên","rising"]:v==="FALLING"?["Đang xuống","falling"]:v==="TURNING"?["Đang đổi nước","turning"]:["Chưa xác định","unknown"]}
function panel(){style();if($("tidePanel"))return;const host=document.createElement("section");host.id="tidePanel";host.className="panel tide-panel";host.innerHTML=`<div class="panel-head premium-head"><div><small>THỦY TRIỀU</small><h2>Triều & đổi nước</h2></div><span class="section-kicker">COPERNICUS · FES2014</span></div><div class="tide-grid"><div class="tide-now"><span>Mực triều mô hình</span><b id="tideHeight">—</b><small>m so với mực biển trung bình mô hình</small><i id="tideTrend" class="tide-trend unknown">Chưa có dữ liệu</i></div><div class="tide-chart-wrap"><svg id="tideSpark" viewBox="0 0 640 150" preserveAspectRatio="none" aria-label="Đường triều 24 giờ"></svg><div class="tide-chart-caption"><span>Bây giờ</span><span>+24 giờ</span></div></div><div class="tide-metrics"><div><span>Triều cao kế tiếp</span><b id="nextHigh">—</b><small id="nextHighHeight">—</small></div><div><span>Triều thấp kế tiếp</span><b id="nextLow">—</b><small id="nextLowHeight">—</small></div><div><span>Đổi nước gần nhất</span><b id="nextTurn">—</b><small id="nextTurnType">—</small></div><div><span>Biên độ 24h</span><b id="tideRange">—</b><small>m · max − min mô hình</small></div></div></div><div class="tide-foot"><span id="tideSource">FES2014 qua Copernicus Marine</span><span>Không phải số đo trạm hoặc mực nước theo hải đồ cảng. Chưa dùng tự động để phát GO/HOLD.</span></div>`;const aq=$("airQualityPanel"),conditions=document.querySelector(".conditions");(aq||conditions)?.insertAdjacentElement("afterend",host)}
function draw(rows=[]){const svg=$("tideSpark");if(!svg)return;const now=Date.now(),end=now+24*3600000,part=rows.filter(r=>{const t=Date.parse(r.time_iso);return Number.isFinite(t)&&t>=now-3600000&&t<=end});if(part.length<2){svg.innerHTML='<text x="320" y="78" text-anchor="middle" class="tide-empty">Chưa có chuỗi triều 24 giờ</text>';return}const vals=part.map(r=>num(r.height_m)).filter(v=>v!==null),min=Math.min(...vals),max=Math.max(...vals),span=Math.max(.05,max-min);const points=part.map((r,i)=>{const x=20+i*(600/Math.max(1,part.length-1)),y=125-(num(r.height_m)-min)/span*95;return `${x.toFixed(1)},${y.toFixed(1)}`}).join(" ");const first=points.split(" ")[0],last=points.split(" ").at(-1);svg.innerHTML=`<defs><linearGradient id="tideFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#168bd0" stop-opacity=".28"/><stop offset="1" stop-color="#168bd0" stop-opacity=".02"/></linearGradient></defs><line x1="20" y1="125" x2="620" y2="125" class="tide-axis"/><polygon points="20,125 ${points} 620,125" fill="url(#tideFill)"/><polyline points="${points}" fill="none" class="tide-line"/>`}
function render(){panel();const p=tide?.points?.[currentPoint]||{},ready=tide?.status==="POINT_NUMERIC_READY"&&num(p.current_height_m)!==null,[trend,cls]=trendLabel(p.trend);$("tideHeight").textContent=ready?fmt(p.current_height_m,2):"—";$("tideTrend").textContent=ready?trend:"Chưa có dữ liệu";$("tideTrend").className=`tide-trend ${ready?cls:"unknown"}`;$("nextHigh").textContent=ready?timeLabel(p.next_high):"—";$("nextHighHeight").textContent=ready&&num(p.next_high?.height_m)!==null?`${fmt(p.next_high.height_m,2)} m`:"—";$("nextLow").textContent=ready?timeLabel(p.next_low):"—";$("nextLowHeight").textContent=ready&&num(p.next_low?.height_m)!==null?`${fmt(p.next_low.height_m,2)} m`:"—";$("nextTurn").textContent=ready?timeLabel(p.next_turn):"—";$("nextTurnType").textContent=ready?(p.next_turn?.type==="HIGH"?"đỉnh triều":p.next_turn?.type==="LOW"?"chân triều":"—"):"—";$("tideRange").textContent=ready?fmt(p.range_24h_m,2):"—";$("tideSource").textContent=`FES2014 qua Copernicus Marine · cập nhật ${ageLabel(tide.generated_at)}`;draw(ready?p.series:[]);document.body.dataset.tide=ready?cls:"unknown"}
async function load(){try{const r=await fetch("/weather/tide.json",{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const data=await r.json();tide={...tide,...data,points:data?.points&&typeof data.points==="object"?data.points:{}}}catch(e){tide={...tide,status:"UNAVAILABLE",detail:e.message}}render()}
function install(){panel();document.querySelectorAll(".point-tabs button").forEach(btn=>btn.addEventListener("click",()=>setTimeout(render,0)));load();setInterval(load,REFRESH)}
window.WeatherLabTide={install,render,load};
})();